def golden_cases(item_id):
    payload = json.loads(zlib.decompress(base64.b85decode(_PAYLOAD)))
    try:
        flat_groups = payload[item_id]
    except KeyError:
        raise KeyError(item_id) from None
    if len(flat_groups) != 5 or any(len(group) != 4 for group in flat_groups):
        raise AssertionError(f"invalid frozen golden shape for {item_id}")
    return [
        [(entry["data"], entry["expected"]) for entry in group]
        for group in flat_groups
    ]
